<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<if condition="empty($now_category)">						<a href="{pigcms{:U('Employee/category')}" class="on">分类列表</a>|						<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/cat_add',array('cat_fid'=>intval($_GET['cat_fid'])))}','添加主分类',680,500,true,false,false,addbtn,'add',true);">添加主分类</a>					<elseif condition="empty($_GET['cat_pfcid'])" />						<a href="{pigcms{:U('Employee/category')}">分类列表</a>|						<a href="{pigcms{:U('Employee/category',array('cat_fid'=>$_GET['cat_fid']))}" class="on">{pigcms{$now_category.cat_name} - 子分类列表</a>|						<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/cat_add',array('cat_fid'=>intval($_GET['cat_fid'])))}','添加子分类',680,500,true,false,false,addbtn,'add',true);">添加子分类</a>					<else/>                        <a href="{pigcms{:U('Employee/category')}">分类列表</a>|                        <a href="{pigcms{:U('Employee/category',array('cat_fid'=>$_GET['cat_pfcid']))}">{pigcms{$pf_now_category.cat_name} - 子分类列表</a>|                        <a href="{pigcms{:U('Employee/category',array('cat_fid'=>$_GET['cat_fid'], 'cat_pfcid'=>$_GET['cat_pfcid']))}" class="on">{pigcms{$now_category.cat_name} - 子分类列表</a>|                        <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/cat_add',array('cat_fid'=>intval($_GET['cat_fid']), 'cat_pfcid'=>intval($_GET['cat_pfcid'])))}','添加子分类',580,460,true,false,false,addbtn,'add',true);">添加子分类</a>                    </if>				</ul>			</div>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<if condition="empty($_GET['cat_fid'])">								<col/>								<col/>								<col/>								<col/>								<col/>							</if>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th>排序</th>								<th>编号</th>								<th>名称</th>								<th>短标记(url)</th>								<if condition="empty($_GET['cat_fid']) || empty($_GET['cat_pfcid'])">									<th>查看子分类</th>								</if>                                <if condition="empty($_GET['cat_fid'])">                                    <th>自定义填写项管理</th>                                </if>								<th>状态</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($category_list)">								<volist name="category_list" id="vo">									<tr>										<td>{pigcms{$vo.cat_sort}</td>										<td>{pigcms{$vo.cat_id}</td>										<td><if condition="$vo['is_hot']"><font color="red">{pigcms{$vo.cat_name}</font><else/>{pigcms{$vo.cat_name}</if></td>										<td>{pigcms{$vo.cat_url}</td>										<if condition="empty($_GET['cat_fid'])">											<td><a href="{pigcms{:U('Employee/category',array('cat_fid'=>$vo['cat_id']))}">查看子分类</a></td>                                        <elseif condition="!empty($_GET['cat_fid']) && empty($_GET['cat_pfcid'])"/>                                            <td><a href="{pigcms{:U('Employee/category',array('cat_fid'=>$vo['cat_id'], 'cat_pfcid'=>$_GET['cat_fid']))}">查看子分类</a></td>                                        </if>                                        <if condition="empty($_GET['cat_fid'])">                                            <td><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/write_field',array('cat_id'=>$vo['cat_id']))}','自定义填写项',750,680,true,false,false,false,'detail',true);">自定义填写项</a></td>                                        </if>                                        <td><if condition="$vo['cat_status'] eq 1"><font color="green">启用</font><elseif condition="$vo['cat_status'] eq 2"/><font color="red">待审核</font><else/><font color="red">关闭</font></if></td>										<td class="textcenter">                                            <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/cat_edit',array('cat_id'=>$vo['cat_id'],'frame_show'=>true))}<if condition="$vo['cat_fid']">&cat_fid={pigcms{$vo.cat_fid}</if>','查看分类信息',680,500,true,false,false,false,'detail',true);">查看</a>                                            | <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Employee/cat_edit',array('cat_id'=>$vo['cat_id']))}<if condition="$vo['cat_fid']">&cat_fid={pigcms{$vo.cat_fid}</if>','编辑分类信息',680,500,true,false,false,editbtn,'edit',true);">编辑</a>                                            | <a href="javascript:void(0);" class="delete_row" parameter="cat_id={pigcms{$vo.cat_id}" url="{pigcms{:U('Employee/cat_del')}" tip="如果分类下存在从业人员，不可删除。">删除</a></td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="9">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>